/* Clepso web dashboard (/app). No libraries: plain fetch against Supabase Auth and the REST API.
 *
 * The accounts project (URL and publishable key) comes from /app/config.js, generated by scripts/build-site.py from
 * the uncommitted Config/Sync.local.xcconfig; without it the page says accounts aren't configured and makes no request.
 * The publishable key grants nothing by itself: every table is protected by row-level security, so the signed-in
 * user's token reaches only that user's rows.
 *
 * Sign-in: a one-time email link with PKCE. The verifier stays in this browser's localStorage, so the link works only
 * in the browser that asked for it. The link returns to /app?code=…, which is exchanged for a session and then removed
 * from the address bar. The session (access and refresh token) is kept in localStorage, as supabase-js does.
 * A link's own error text is never shown (anyone can craft a URL), only our own words for known error codes.
 */
(() => {
  "use strict";
  document.documentElement.classList.add("js");

  const root = document.getElementById("app");
  const live = document.getElementById("app-live");
  if (!root) return;

  const SESSION = "clepso.session", PENDING = "clepso.signin";
  const store = {
    get(k) { try { return JSON.parse(localStorage.getItem(k) || "null"); } catch { return null; } },
    set(k, v) { try { localStorage.setItem(k, JSON.stringify(v)); } catch { /* storage blocked: the session lasts this page only */ } },
    del(k) { try { localStorage.removeItem(k); } catch { /* nothing to remove */ } },
  };
  let memory = null;   // the session, also when storage is blocked
  const getSession = () => memory || (memory = store.get(SESSION));
  const setSession = s => { memory = s; s ? store.set(SESSION, s) : store.del(SESSION); };

  // ------------------------------------------------------------------------------------------------------- config
  function readConfig() {
    const c = window.CLEPSO_ACCOUNTS;
    if (!c || typeof c.url !== "string" || typeof c.key !== "string") return null;
    let u;
    try { u = new URL(c.url); } catch { return null; }
    const local = u.protocol === "http:" && (u.hostname === "127.0.0.1" || u.hostname === "localhost");
    if (u.protocol !== "https:" && !local) return null;
    const key = c.key.trim();
    if (!key || key.startsWith("sb_secret_") || /\s/.test(key)) return null;   // a secret key never belongs in a page
    return { url: u.origin, key };
  }
  const cfg = readConfig();
  const REDIRECT = location.origin + "/app";

  // -------------------------------------------------------------------------------------------------- formatting
  const esc = s => String(s ?? "").replace(/[&<>"']/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
  const int = n => Math.round(Number(n) || 0).toLocaleString("en-GB");
  function compact(n) {
    n = Number(n) || 0;
    for (const [size, suffix] of [[1e12, "T"], [1e9, "B"], [1e6, "M"], [1e3, "K"]]) {
      if (n >= size) { const v = n / size; return (v >= 100 || v === Math.round(v) ? v.toFixed(0) : v.toFixed(1)) + suffix; }
    }
    return String(Math.round(n));
  }
  const pct = v => v == null ? "—" : `${Math.round(Number(v))}%`;
  const pad = n => String(n).padStart(2, "0");
  const label = d => `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
  const parseDay = s => { const [y, m, d] = s.split("-").map(Number); return new Date(y, m - 1, d); };
  const WD = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
  const MO = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
  const dayShort = s => { const d = parseDay(s); return `${WD[d.getDay()]} ${d.getDate()} ${MO[d.getMonth()]}`; };
  const dayLong = s => { const d = parseDay(s); return `${WD[d.getDay()]} ${d.getDate()} ${MO[d.getMonth()]} ${d.getFullYear()}`; };

  /** The last 14 local days, oldest first. */
  function lastDays(n = 14) {
    const out = [], now = new Date();
    for (let i = n - 1; i >= 0; i--) out.push(label(new Date(now.getFullYear(), now.getMonth(), now.getDate() - i)));
    return out;
  }

  // ---------------------------------------------------------------------------------------------------- network
  class HttpError extends Error {
    constructor(status, code) { super(`HTTP ${status}`); this.status = status; this.code = code; }
  }
  async function call(url, options) {
    let response;
    try { response = await fetch(url, { cache: "no-store", credentials: "omit", ...options }); }
    catch { throw new HttpError(0, "network"); }
    let data = null;
    const text = await response.text();
    if (text) { try { data = JSON.parse(text); } catch { data = null; } }
    if (!response.ok) {
      const code = data && (data.error_code || data.code || data.error);
      throw new HttpError(response.status, typeof code === "string" ? code.slice(0, 40) : null);
    }
    return data;
  }
  function authCall(path, body, token) {
    const headers = { apikey: cfg.key, "Content-Type": "application/json" };
    if (token) headers.Authorization = `Bearer ${token}`;
    return call(`${cfg.url}/auth/v1/${path}`, { method: "POST", headers, body: JSON.stringify(body || {}) });
  }
  function keep(data) {
    if (!data || !data.access_token || !data.refresh_token) throw new HttpError(500, "bad_response");
    const s = { access: data.access_token, refresh: data.refresh_token, expiresAt: Date.now() + (Number(data.expires_in) || 3600) * 1000,
                email: data.user && data.user.email || null };
    setSession(s);
    return s;
  }
  /** A session valid for at least another minute (refreshed if needed), or null when signed out. */
  async function validSession(force = false) {
    const s = getSession();
    if (!s) return null;
    if (!force && s.expiresAt - Date.now() > 60_000) return s;
    try { return keep(await authCall("token?grant_type=refresh_token", { refresh_token: s.refresh })); }
    catch (err) {
      if (err.status === 400 || err.status === 401 || err.status === 403) { setSession(null); return null; }
      throw err;
    }
  }
  async function rest(path, init = {}) {
    for (let attempt = 0; attempt < 2; attempt++) {
      const s = await validSession(attempt > 0);
      if (!s) throw new HttpError(401, "signed_out");
      try {
        return await call(`${cfg.url}/rest/v1/${path}`, { ...init, headers: { apikey: cfg.key, Authorization: `Bearer ${s.access}`,
                                                                            "Content-Type": "application/json", ...(init.headers || {}) } });
      } catch (err) {
        if (err.status !== 401 || attempt > 0) throw err;   // an expired token: refresh once and retry
      }
    }
  }

  // PKCE (RFC 7636): S256 challenge of a random verifier.
  const b64url = bytes => btoa(String.fromCharCode(...new Uint8Array(bytes))).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
  async function pkce() {
    const verifier = b64url(crypto.getRandomValues(new Uint8Array(32)));
    const challenge = b64url(await crypto.subtle.digest("SHA-256", new TextEncoder().encode(verifier)));
    return { verifier, challenge };
  }

  // ----------------------------------------------------------------------------------------------------- render
  let acted = false;   // focus moves to the new heading only after the user did something, never on first load
  function show(html, { focus = acted, say } = {}) {
    root.innerHTML = html;
    root.removeAttribute("aria-busy");
    if (say && live) { live.textContent = ""; setTimeout(() => { live.textContent = say; }, 50); }
    if (focus) root.querySelector("h1")?.focus({ preventScroll: false });
  }
  const top = (title, lede, extra = "") =>
    `<header class="app-top"><p class="eyebrow">Clepso / <b>web dashboard</b></p><h1 tabindex="-1">${title}${extra}</h1>${lede ? `<p class="lede">${lede}</p>` : ""}</header>`;
  const row = (id, name, line, body, cls = "") =>
    `<section class="row ${cls}" aria-labelledby="h-${id}"><div class="row-head"><h2 id="h-${id}">${name}</h2><p>${line}</p></div><div class="row-body">${body}</div></section>`;
  const loading = text => `<div class="loading" role="status"><i aria-hidden="true"></i>${esc(text)}</div>`;

  // Messages are plain text; escaped here so no caller can ever put markup (or a link's own error text) on the page.
  function notice(kind, text) { return text ? `<div class="note ${kind}" role="${kind === "err" ? "alert" : "status"}"><p>${esc(text)}</p></div>` : ""; }

  // Unconfigured deployment: nothing to sign in to, no request is ever made.
  function renderUnconfigured() {
    show(top("Web dashboard", "Your Clepso goals and usage, anywhere you sign in.") +
      row("accounts", "Accounts", "Optional. Clepso works fully on your Mac without one.",
        `<div class="empty" role="status"><strong>Accounts aren't configured for this deployment</strong>
        This copy of the site was built without an accounts project, so there is nothing to sign in to here.
        Clepso on your Mac works fully without an account.</div>
        <p class="chart-note" style="margin-top:14px">What signing in would upload is listed on the <a href="/privacy/#upload">Privacy</a> page.</p>`), { focus: false });
  }

  // Signed out: email link form, or "check your email" after asking for one.
  function renderSignIn(message = "", kind = "warn") {
    const pending = store.get(PENDING);
    const sent = pending && pending.sentAt && Date.now() - pending.sentAt < 60 * 60 * 1000;
    const form = sent ? `
      <div class="note" role="status"><p><b>Check your email.</b> We sent a sign-in link to <b>${esc(pending.email)}</b>.</p>
      <p>Open it in this browser on this device: the link only works where you asked for it. It expires after an hour.</p></div>
      <div class="btns"><button class="btn" type="button" data-resend>Send it again</button><button class="btn" type="button" data-other>Use another email</button></div>`
      : `
      <form class="inline-form" data-signin novalidate>
        <div class="field"><label for="email">Email</label>
          <input id="email" name="email" type="email" autocomplete="email" inputmode="email" spellcheck="false" required placeholder="you@example.com" aria-describedby="email-help"></div>
        <button class="btn primary" type="submit">Email me a link</button>
      </form>
      <p class="chart-note" id="email-help" style="margin-top:10px">A one-time link, no password. Signing in with a new address creates an account.</p>`;
    show(top("Sign in", "See the daily counts your Mac uploads: activity, tokens per model, limits, agents and goals.") +
      row("signin", "Sign in", "Optional. The same account as Clepso on your Mac (Clepso › Account).", notice(kind, message) + form) +
      row("what", "What's here", "Daily counts only. Never prompts, replies, file paths or project names.",
        `<ul class="plain">
          <li>The last 14 days of Claude Code activity and tokens per model</li>
          <li>Each day's 5-hour peak and where the 7-day limit finished</li>
          <li>Agents per task, your goals day by day, your name and plan</li></ul>
        <p class="chart-note">Every field is listed on the <a href="/privacy/#upload">Privacy</a> page. You can delete the account here at any time.</p>`),
      { say: message || undefined });

    const formEl = root.querySelector("[data-signin]");
    if (formEl) {
      formEl.addEventListener("submit", ev => { ev.preventDefault(); acted = true; requestLink(formEl.email.value.trim(), formEl); });
    }
    root.querySelector("[data-resend]")?.addEventListener("click", ev => (acted = true, requestLink(pending.email, null, ev.currentTarget)));
    root.querySelector("[data-other]")?.addEventListener("click", () => { acted = true; store.del(PENDING); renderSignIn(); root.querySelector("#email")?.focus(); });
  }

  async function requestLink(email, formEl, button) {
    const btn = button || formEl?.querySelector("button[type=submit]");
    const fail = text => {
      if (formEl) {
        formEl.parentElement.querySelector(".note")?.remove();
        formEl.insertAdjacentHTML("beforebegin", notice("err", text));
        formEl.email.setAttribute("aria-invalid", "true");
        formEl.email.focus();
      } else {
        renderSignIn(text, "err");
      }
      if (btn) { btn.disabled = false; btn.textContent = button ? "Send it again" : "Email me a link"; }
    };
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email || "")) return fail("Enter an email address, like you@example.com.");
    if (btn) { btn.disabled = true; btn.textContent = "Sending…"; }
    try {
      const { verifier, challenge } = await pkce();
      await call(`${cfg.url}/auth/v1/otp?redirect_to=${encodeURIComponent(REDIRECT)}`, {
        method: "POST", headers: { apikey: cfg.key, "Content-Type": "application/json" },
        body: JSON.stringify({ email, create_user: true, code_challenge: challenge, code_challenge_method: "s256" }),
      });
      store.set(PENDING, { verifier, email, sentAt: Date.now() });
      renderSignIn();
      root.querySelector("h1")?.focus();
      if (live) live.textContent = `Sign-in link sent to ${email}.`;
    } catch (err) {
      fail(err.status === 429 ? "Too many links asked for. Wait a minute, then try again."
        : err.status === 0 ? "Couldn't reach the sign-in service. Check your connection and try again."
        : err.status === 400 || err.status === 422 ? "That address wasn't accepted. Check it and try again."
        : "Sign-in isn't available right now. Try again in a few minutes.");
    }
  }

  // The link brings ?code=… (or an error) back to /app. Exchange the code, then clean the address bar.
  async function handleReturn() {
    const q = new URLSearchParams(location.search), h = new URLSearchParams(location.hash.slice(1));
    const code = q.get("code"), error = q.get("error") || h.get("error"), errorCode = q.get("error_code") || h.get("error_code");
    if (!code && !error) return null;
    history.replaceState(null, "", location.pathname);   // the code is single-use; keep it out of history and bookmarks
    if (error) {
      return errorCode === "otp_expired" ? "That link has expired or was already used. Ask for a new one below."
        : "Sign-in didn't complete. Ask for a new link below.";
    }
    const pending = store.get(PENDING);
    if (!pending || !pending.verifier) {
      return "This link was asked for in another browser or on another device. Open it there, or ask for a new link here.";
    }
    show(top("Signing in", "") + loading("Checking your link…"), { focus: false });
    try {
      keep(await authCall("token?grant_type=pkce", { auth_code: code, code_verifier: pending.verifier }));
      store.del(PENDING);
      return null;
    } catch (err) {
      if (err.status === 0) return "Couldn't reach the sign-in service. Check your connection, then ask for a new link.";
      return "That link has expired, was already used, or belongs to an older request. Ask for a new one below.";
    }
  }

  // ------------------------------------------------------------------------------------------------- dashboard
  async function loadData() {
    const days = lastDays(), first = days[0];
    const get = path => rest(path, { method: "GET" });
    const [profile, activity, tokens, totals, limits, agents, goals, goalDays, lastActivity, lastLimits] = await Promise.all([
      get("profiles?select=display_name,plan_label"),
      get(`daily_activity?select=day,messages,sessions,active&day=gte.${first}&order=day.asc`),
      get(`daily_model_tokens?select=day,model,tokens&day=gte.${first}&order=day.asc`),
      get("model_totals?select=model,input,output,cache_read,cache_write&order=output.desc"),
      get(`daily_limits?select=day,five_hour_peak_pct,seven_day_end_pct&day=gte.${first}&order=day.asc`),
      get(`daily_agents?select=day,tasks,agents,by_type&day=gte.${first}&order=day.asc`),
      get("goals?select=kind,target"),
      get(`goal_days?select=day,kind,value,met&day=gte.${first}&order=day.asc`),
      get("daily_activity?select=day&order=day.desc&limit=1"),
      get("daily_limits?select=day&order=day.desc&limit=1"),
    ]);
    return { days, profile: (profile || [])[0] || {}, activity: activity || [], tokens: tokens || [], totals: totals || [],
             limits: limits || [], agents: agents || [], goals: goals || [], goalDays: goalDays || [],
             latest: [lastActivity, lastLimits].flatMap(r => r || []).map(r => r.day).sort().pop() || null };
  }

  async function renderDashboard(message = "") {
    root.setAttribute("aria-busy", "true");
    show(top("Your dashboard", "") + loading("Loading your data…"), { focus: false });
    let data;
    try { data = await loadData(); }
    catch (err) {
      if (err.status === 401) { setSession(null); return renderSignIn("Your session ended. Sign in again to see your data.", "warn"); }
      show(top("Your dashboard", "") +
        notice("err", err.status === 0 ? "Couldn't reach the server. Check your connection." : "Couldn't load your data just now.") +
        `<div class="btns"><button class="btn primary" type="button" data-retry>Try again</button><button class="btn" type="button" data-signout>Sign out</button></div>`,
        { say: "Couldn't load your data." });
      root.querySelector("[data-retry]").addEventListener("click", () => { acted = true; renderDashboard(); });
      root.querySelector("[data-signout]").addEventListener("click", () => { acted = true; signOut(); });
      return;
    }
    const s = getSession() || {};
    const name = (data.profile.display_name || "").trim();
    const uploaded = data.goals.length > 0 || data.totals.length > 0 || !!data.latest;
    const lede = `Signed in as ${esc(s.email || "you")}` +
      (data.latest ? ` · latest day uploaded: ${esc(dayShort(data.latest))}` : "") + "." + (uploaded ? " The last 14 days, as your Mac uploaded them." : "");
    const plan = `<span class="pill">${esc(data.profile.plan_label || "Plan not set")}</span>`;
    let html = top(name ? `Hello, ${esc(name)}` : "Your dashboard", lede, plan) + notice("note", message);
    if (!uploaded) {
      html += row("start", "Nothing yet", "Your Mac uploads once an hour after you sign in there.",
        `<div class="empty" role="status"><strong>No uploads yet: sign in on your Mac</strong>
         <ol><li>Open Clepso on your Mac, then Dashboard › Account.</li>
         <li>Sign in with the same email${s.email ? ` (<b>${esc(s.email)}</b>)` : ""}.</li>
         <li>Within the hour your daily counts appear here. Activity and tokens need Claude Code stats turned on in Clepso.</li></ol></div>`);
    } else {
      html += activitySection(data) + tokensSection(data) + limitsSection(data) + agentsSection(data) + goalsSection(data);
    }
    html += accountSection(data, s);
    show(html, { say: uploaded ? "Your dashboard has loaded." : "Signed in. No uploads yet." });
    wireAccount();
  }

  function activitySection({ days, activity }) {
    const line = "Claude Code messages and sessions, day by day.";
    if (!activity.length) {
      return row("activity", "Activity", line, `<div class="empty">No activity in these 14 days. It's uploaded when Claude Code stats are on in Clepso (Settings or Stats › Overview).</div>`);
    }
    const by = Object.fromEntries(activity.map(r => [r.day, r]));
    const max = Math.max(1, ...activity.map(r => r.messages));
    const messages = activity.reduce((a, r) => a + r.messages, 0), sessions = activity.reduce((a, r) => a + r.sessions, 0);
    const active = activity.filter(r => r.active).length;
    const colsHtml = days.map(d => {
      const r = by[d];
      if (!r) return `<i class="nodata" title="${esc(dayShort(d))}: no data"></i>`;
      if (!r.messages) return `<i class="zero" style="height:2px" title="${esc(dayShort(d))}: no messages"></i>`;
      return `<i style="height:${Math.max(2, 100 * r.messages / max).toFixed(1)}%" title="${esc(dayShort(d))}: ${int(r.messages)} messages, ${int(r.sessions)} sessions"></i>`;
    }).join("");
    const xs = days.map(d => `<span>${parseDay(d).getDate()}</span>`).join("");
    const rows = days.slice().reverse().map(d => {
      const r = by[d];
      return `<tr><td>${esc(dayShort(d))}</td>${r ? `<td class="num">${int(r.messages)}</td><td class="num">${int(r.sessions)}</td><td>${r.active ? "Yes" : "No"}</td>` : `<td colspan="3">No data</td>`}</tr>`;
    }).join("");
    return row("activity", "Activity", line, `
      <div class="figs"><div><b>${int(messages)}</b><span>Messages</span></div><div><b>${int(sessions)}</b><span>Sessions</span></div>
      <div><b>${active}<small style="font-size:.6em">/14</small></b><span>Active days</span></div></div>
      <div class="cols" aria-hidden="true">${colsHtml}</div><div class="cols-x" aria-hidden="true">${xs}</div>
      <p class="chart-note">Messages per day, ${esc(dayShort(days[0]))} to ${esc(dayShort(days[13]))}. A hatched column is a day with no upload.</p>
      <details class="data"><summary>Show as a table</summary><div class="table-wrap"><table><caption class="sr">Activity, newest first</caption>
      <thead><tr><th scope="col">Day</th><th scope="col" class="num">Messages</th><th scope="col" class="num">Sessions</th><th scope="col">Active</th></tr></thead>
      <tbody>${rows}</tbody></table></div></details>`);
  }

  function tokensSection({ tokens, totals }) {
    const line = "Tokens each model used in these 14 days, and all-time totals by kind.";
    if (!tokens.length && !totals.length) {
      return row("tokens", "Tokens per model", line, `<div class="empty">No token counts uploaded. They come from Claude Code's statistics file when Claude Code stats are on in Clepso.</div>`);
    }
    const sum = {};
    tokens.forEach(r => { sum[r.model] = (sum[r.model] || 0) + Number(r.tokens); });
    const list = Object.entries(sum).sort((a, b) => b[1] - a[1]);
    const total = list.reduce((a, [, v]) => a + v, 0), max = Math.max(1, ...list.map(([, v]) => v));
    const bars = list.length ? `<ul class="hbars" aria-label="Tokens per model, last 14 days">${list.map(([m, v]) =>
      `<li><span class="name">${esc(m)}</span><span class="val">${compact(v)}<small>${total ? Math.round(100 * v / total) : 0}%</small></span>
       <span class="bar" aria-hidden="true"><i style="width:${(100 * v / max).toFixed(1)}%"></i></span></li>`).join("")}</ul>`
      : `<p class="chart-note">No tokens counted in these 14 days.</p>`;
    const models = totals.length ? `<h3 style="margin:22px 0 10px;font-size:13px;color:var(--p-text2)">All time, by kind</h3><div class="models">${totals.map(t =>
      `<div class="model"><h3>${esc(t.model)}</h3><dl><div><dt>Output</dt><dd class="out">${compact(t.output)}</dd></div><div><dt>Input</dt><dd>${compact(t.input)}</dd></div>
       <div><dt>Cache read</dt><dd>${compact(t.cache_read)}</dd></div><div><dt>Cache write</dt><dd>${compact(t.cache_write)}</dd></div></dl></div>`).join("")}</div>
       <p class="chart-note">Output is what the model wrote; most tokens are cache reads. <a href="/metrics/#tokens">What the kinds mean</a>.</p>` : "";
    return row("tokens", "Tokens per model", line,
      `<div class="figs"><div><b>${compact(total)}</b><span>Tokens, 14 days</span></div><div><b>${list.length}</b><span>${list.length === 1 ? "Model" : "Models"}</span></div></div>${bars}${models}`);
  }

  function level(v) { return v == null ? "lvl-none" : v >= 95 ? "lvl-max" : v >= 80 ? "lvl-warn" : ""; }
  function limitsSection({ days, limits }) {
    const line = "Each day's 5-hour peak, and where the 7-day limit stood at the end of the day.";
    if (!limits.length) return row("limits", "Limits", line, `<div class="empty">No limit readings in these 14 days. Clepso records them while Claude Code runs on your Mac.</div>`);
    const by = Object.fromEntries(limits.map(r => [r.day, r]));
    const lim = (tag, name, v) => `<div class="lim ${level(v)}"><span aria-hidden="true">${tag}</span><div class="meter2" aria-hidden="true">${v == null ? "" : `<i style="width:${Math.min(100, Number(v))}%"></i>`}</div>
      <b><span class="sr">${name} </span>${v == null ? "—<span class=sr> not seen</span>" : pct(v)}</b></div>`;
    const items = days.slice().reverse().filter(d => by[d]).map(d => {
      const r = by[d];
      return `<li><span class="lim-day">${esc(dayShort(d))}</span>${lim("5H", "5-hour peak", r.five_hour_peak_pct)}${lim("7D", "7-day at day end", r.seven_day_end_pct)}</li>`;
    }).join("");
    const peak = Math.max(...limits.map(r => Number(r.five_hour_peak_pct) || 0));
    const over = limits.filter(r => Number(r.five_hour_peak_pct) >= 80).length;
    return row("limits", "Limits", line, `
      <div class="figs"><div><b>${pct(peak)}</b><span>Highest 5-hour peak</span></div><div><b>${over}</b><span>${over === 1 ? "Day" : "Days"} at 80% or more</span></div></div>
      <p class="legend"><span><i style="background:var(--p-accent)"></i>Under 80%</span><span><i style="background:var(--p-amber)"></i>80% or more</span><span><i style="background:var(--p-rust)"></i>95% or more</span><span><i style="box-shadow:inset 0 0 0 1px var(--a-edge)"></i>Not seen</span></p>
      <ul class="limits" aria-label="Limits by day, newest first">${items}</ul>
      <p class="chart-note">Days without a reading are left out. 5H: the 5-hour limit's highest point that day. 7D: the 7-day limit at the day's last reading.</p>`);
  }

  const AGENT_TYPES = [["Explore", "Explore"], ["Plan", "Plan"], ["general-purpose", "General"], ["claude-code-guide", "Guide"],
                       ["statusline-setup", "Status line"], ["custom", "Custom"], ["unknown", "Unknown"]];
  function agentsSection({ days, agents }) {
    const line = "Subagents Claude Code started per task. A task is one prompt, from sending it until Claude stops.";
    if (!agents.length) return row("agents", "Agents per task", line, `<div class="empty">No tasks uploaded for these 14 days. Counting agents is optional: turn it on in Clepso's Settings.</div>`);
    const tasks = agents.reduce((a, r) => a + r.tasks, 0), subs = agents.reduce((a, r) => a + r.agents, 0);
    const types = {};
    agents.forEach(r => Object.entries(r.by_type || {}).forEach(([k, v]) => { types[k] = (types[k] || 0) + (Number(v) || 0); }));
    const known = new Map(AGENT_TYPES);
    const rank = k => { const i = AGENT_TYPES.findIndex(t => t[0] === k); return i < 0 ? 99 : i; };
    const list = Object.entries(types).filter(([, v]) => v > 0).sort((a, b) => rank(a[0]) - rank(b[0]));
    const max = Math.max(1, ...list.map(([, v]) => v));
    const bars = list.length ? `<ul class="hbars" aria-label="Subagents by type, last 14 days">${list.map(([k, v]) =>
      `<li><span class="name">${esc(known.get(k) || k)}</span><span class="val">${int(v)}</span><span class="bar" aria-hidden="true"><i style="width:${(100 * v / max).toFixed(1)}%"></i></span></li>`).join("")}</ul>` : "";
    const by = Object.fromEntries(agents.map(r => [r.day, r]));
    const rows = days.slice().reverse().filter(d => by[d]).map(d => {
      const r = by[d];
      return `<tr><td>${esc(dayShort(d))}</td><td class="num">${int(r.tasks)}</td><td class="num">${int(r.agents)}</td><td class="num">${r.tasks ? (r.agents / r.tasks).toFixed(1) : "—"}</td></tr>`;
    }).join("");
    return row("agents", "Agents per task", line, `
      <div class="figs"><div><b>${int(tasks)}</b><span>Tasks</span></div><div><b>${int(subs)}</b><span>Subagents</span></div>
      <div><b>${tasks ? (subs / tasks).toFixed(1) : "—"}</b><span>Agents per task</span></div></div>${bars}
      <details class="data"><summary>Show each day</summary><div class="table-wrap"><table><caption class="sr">Agents per task by day, newest first</caption>
      <thead><tr><th scope="col">Day</th><th scope="col" class="num">Tasks</th><th scope="col" class="num">Agents</th><th scope="col" class="num">Per task</th></tr></thead>
      <tbody>${rows}</tbody></table></div></details>`);
  }

  const GOALS = {
    activeDays: { title: "Active days a week", off: "active days a week", target: t => `${t} of 7 days`, value: v => `${Math.round(v)} of the last 7 days active` },
    fiveHourPeak: { title: "Keep the 5-hour limit under", off: "keep the 5-hour limit under a target", target: t => `under ${t}%`, value: v => `peak ${Math.round(v)}%` },
    weeklyFinish: { title: "Finish the week under", off: "finish the week under a target", target: t => `under ${t}%`, value: v => `${Math.round(v)}% at day end` },
  };
  function goalsSection({ days, goals, goalDays }) {
    const line = "Targets you set on your Mac, and each day's result.";
    if (!goals.length) return row("goals", "Goals", line, `<div class="empty">No goals uploaded yet. Set them in Clepso › Goals; they arrive with the next upload.</div>`);
    const order = Object.keys(GOALS);
    const sorted = goals.filter(g => GOALS[g.kind]).sort((a, b) => order.indexOf(a.kind) - order.indexOf(b.kind));
    const off = sorted.filter(g => g.target == null);
    const blocks = sorted.filter(g => g.target != null).map(g => {
      const def = GOALS[g.kind];
      const by = Object.fromEntries(goalDays.filter(r => r.kind === g.kind).map(r => [r.day, r]));
      let met = 0, over = 0, risk = 0;
      const cells = days.map(d => {
        const r = by[d];
        if (!r) return `<li title="${esc(dayShort(d))}: no data"><span class="sr">${esc(dayLong(d))}: no data</span></li>`;
        const value = r.value == null ? "" : def.value(Number(r.value), r.met);
        const [cls, mark, word] = r.met === true ? ["met", "✓", "met"] : r.met === false ? ["over", "✕", "missed"] : ["risk", "!", "at risk"];
        if (cls === "met") met++; else if (cls === "over") over++; else risk++;
        return `<li class="${cls}" title="${esc(dayShort(d))}: ${word}${value ? ", " + esc(value) : ""}"><span aria-hidden="true">${mark}</span><span class="sr">${esc(dayLong(d))}: ${word}${value ? ", " + esc(value) : ""}</span></li>`;
      }).join("");
      return `<div class="goal"><div class="goal-head"><h3>${esc(def.title)}</h3><span>Target: ${esc(def.target(g.target))}</span></div>
        <ol class="strip" aria-label="${esc(def.title)}, the last 14 days">${cells}</ol>
        <div class="strip-x" aria-hidden="true"><span>${esc(dayShort(days[0]))}</span><span>Today</span></div>
        <p class="goal-sum"><b>${met}</b> met · <b>${over}</b> missed · <b>${risk}</b> at risk · <b>${14 - met - over - risk}</b> no data</p></div>`;
    }).join("");
    const offNote = off.length ? `<p class="chart-note">Turned off on your Mac: ${off.map(g => esc(GOALS[g.kind].off)).join("; ")}.</p>` : "";
    return row("goals", "Goals", line, (blocks || `<div class="empty">Every goal is turned off on your Mac.</div>`) +
      `<p class="legend"><span>✓ Met</span><span>✕ Missed</span><span>! At risk (not decided yet)</span><span>Empty: no data</span></p>` + offNote);
  }

  function accountSection({ profile }, s) {
    return row("account", "Account", "Name and plan come from your Mac (Clepso › Account).", `
      <dl class="kv"><dt>Name</dt><dd>${esc(profile.display_name || "Not set")}</dd><dt>Plan</dt><dd>${esc(profile.plan_label || "Not set")}</dd>
      <dt>Email</dt><dd>${esc(s.email || "—")}</dd></dl>
      <div class="btns"><button class="btn" type="button" data-signout>Sign out</button></div>`) +
      row("danger", "Danger zone", "Deleting the account removes it and everything uploaded, at once.", `
      <p>Clepso on your Mac keeps working and keeps its own data; it signs out the next time it tries to upload.</p>
      <div class="btns"><button class="btn warn" type="button" data-delete aria-expanded="false" aria-controls="confirm">Delete account…</button></div>
      <div class="confirm" id="confirm" hidden>
        <p><b>This can't be undone.</b> Your account, profile, goals and every day of counts uploaded to it are deleted now.</p>
        <div class="field"><label for="confirm-text">Type DELETE to confirm</label>
          <input id="confirm-text" type="text" autocomplete="off" autocapitalize="characters" spellcheck="false" aria-describedby="confirm-help">
          <small id="confirm-help">In capitals, then press Delete my account.</small></div>
        <div class="btns"><button class="btn warn solid" type="button" data-confirm disabled>Delete my account</button><button class="btn" type="button" data-cancel>Cancel</button></div>
        <div data-delete-msg></div>
      </div>`, "danger");
  }

  function wireAccount() {
    root.querySelector("[data-signout]")?.addEventListener("click", () => { acted = true; signOut(); });
    const open = root.querySelector("[data-delete]"), panel = root.querySelector("#confirm");
    if (!open || !panel) return;
    const input = panel.querySelector("input"), go = panel.querySelector("[data-confirm]");
    open.addEventListener("click", () => { acted = true; panel.hidden = false; open.setAttribute("aria-expanded", "true"); input.focus(); });
    panel.querySelector("[data-cancel]").addEventListener("click", () => {
      panel.hidden = true; input.value = ""; go.disabled = true; open.setAttribute("aria-expanded", "false"); open.focus();
    });
    input.addEventListener("input", () => { go.disabled = input.value.trim() !== "DELETE"; });
    input.addEventListener("keydown", ev => { if (ev.key === "Enter" && !go.disabled) go.click(); });
    go.addEventListener("click", async () => {
      go.disabled = true; go.textContent = "Deleting…";
      try {
        await rest("rpc/delete_account", { method: "POST", body: "{}" });
        setSession(null); store.del(PENDING);
        renderSignIn("Your account and everything uploaded to it were deleted.", "note");
      } catch (err) {
        go.textContent = "Delete my account"; go.disabled = input.value.trim() !== "DELETE";
        panel.querySelector("[data-delete-msg]").innerHTML = notice("err", err.status === 0
          ? "Couldn't reach the server. Nothing was deleted; try again."
          : err.status === 401 ? "Your session ended. Sign in again, then delete the account." : "The account couldn't be deleted just now. Nothing was deleted; try again.");
      }
    });
  }

  async function signOut() {
    const s = getSession();
    setSession(null);
    if (s) { try { await authCall("logout?scope=local", {}, s.access); } catch { /* signed out here either way */ } }
    renderSignIn("You're signed out.", "note");
  }

  // -------------------------------------------------------------------------------------------------------- start
  async function start() {
    if (!cfg) return renderUnconfigured();
    if (!window.crypto?.subtle) {
      return show(top("Web dashboard", "") + notice("err", "This browser can't sign in securely here (it needs HTTPS and Web Crypto)."));
    }
    const problem = await handleReturn();
    if (problem && getSession()) return renderDashboard("That sign-in link can't be used again, but you're still signed in.");
    if (problem) return renderSignIn(problem, "err");
    let s;
    try { s = await validSession(); }
    catch { return renderDashboard(); }   // offline: the dashboard shows its own error with Try again
    return s ? renderDashboard() : renderSignIn();
  }
  start();
})();
